    point: `セキュリティ番号を整理：クラウド特化＝27017、ISMS基本＝27001、個人情報（日本）＝15001、品質＝9001、環境＝14001。「27×××」シリーズがセキュリティ、末尾17がクラウド版。`,
    mem: `クラウドは「**イイな**(17)」→ ISMS27001のクラウド版が270**17**。末尾17（イイな）だけ覚える。`,
