        why: `民間企業へのオープンデータ公開は努力義務であり、法的強制力はない。義務規定はあくまで公的機関（国・地方公共団体）に向けられている。「官民」という名称から民間にも義務があると混同しやすいが、官＝義務・民＝努力義務と区別する。`
