    mem: `「国も地方も"開けゴマ"義務、民間は"開けたらいいな"」→ 公的機関は呪文一発で強制開放、民間は任意。"開けゴマ"＝義務で必ず開く、"開けたらいいな"＝努力義務で任意。`,
