    point: `ISMS方針の必須要素は①適用範囲，②情報セキュリティ目標，③継続的改善へのコミットメント。「全社に周知」「トップダウン」もセットで押さえる。`,
    mem: `「機密じゃなく全社公開、改善コミット必須」→ ISMS方針の2大NG：①隠す②ボトムアップ。正解はトップが全社に宣言＋継続改善コミット。`,
