        why: `管理的セキュリティ対策はセキュリティポリシーの策定・規則の制定・監査の実施など「ルール・管理」面からリスクを低減する対策。「関係者以外立入禁止」の規程などが該当し，ICカードシステム自体は物理的対策。`
