    point: `DB設計の順序：概念設計（何を管理するか）→ 論理設計（テーブル構造）→ 物理設計（インデックス等）。この問は一番最初の概念設計フェーズ。`,
    mem: `「概念設計はテーブルじゃなくて、エンティティとリレーションを決める」→ 物理（箱作り）より前が概念設計。`,
