    cat: `テクノロジ`,
    diff: `easy`,
    q: `A社はWebシステムの開発・実行環境をクラウドで調達する。OSやミドルウェアの選定・管理も自社で行いたい場合，最も適切なクラウドサービス形態はどれか。`,
