    q: `アパレル企業の担当者が「SNSで広告を見る→店舗で試着する→ECサイトで購入する→レビューを投稿する」という顧客の一連の行動を感情の変化とともに可視化しようとしている。この目的に合うマーケティング手法はどれか。`,
