    point: `「顧客の行動＋感情＋接点を時系列に可視化」＝カスタマージャーニーマップ。バリューチェーンは「企業内部の活動の流れ」なので混同しないこと。`,
    mem: `バリューチェーンじゃなくて、客の旅（ジャーニー）の地図！→ 感情の起伏つきの路線図`,
