    q: `アパレルブランドが実店舗・公式EC・スマホアプリ・SNSの在庫・購入履歴・ポイントを一元管理し、どのチャネルで購入しても同じ体験を提供する戦略を導入した。この戦略として最も適切なものはどれか。`,
