    q: `IT企業の開発チームが作成したソフトウェアが競合他社の特許を侵害していないかを調べた。弁理士から「特許権は出願日から存続期間があり，期限切れの技術は自由に使える」と説明を受けた。特許権の存続期間として正しいものはどれか（出願日を起点とする）。`,
