        why: `AIバイアス（アルゴリズムバイアス）の典型的な問題。過去の審査データに差別的傾向が含まれていると，AIが同じパターンを学習し偏った判定を下す。公平性・説明可能性（XAI）の確保が倫理面の核心。`
