    point: `AI倫理の問いでは「バイアス・公平性・説明可能性」が中心テーマ。コスト・処理速度・技術仕様の話は倫理的課題ではないと即座に切り捨てる。`,
    mem: `AIバイアス＝「**ア**イ，**バ**カにすんな！」＝偏ったデータ食わせたら偏った判定で差別する`,
