    q: `新規事業の立ち上げ検討にあたり，政府の規制緩和動向・景気の回復傾向・少子高齢化による需要変化・新技術の普及速度をまとめて分析したい。この場合に用いるフレームワークとして最も適切なものはどれか。`,
