    mem: `PEST＝「**P**olitics**E**conomy**S**ociety**T**echじゃなくて，社会全体の大きな流れを見るやつ！」──3C・SWOT・5フォースは全部「業界内・自社内」。PESTだけが外の世界（社会・政治・技術）を見る。`,
