        why: `「市場成長率×市場シェア」の2軸で複数製品を花形・問題児・金のなる木・負け犬に分類するポートフォリオ管理手法。これはある時点での複数製品の比較スナップショットであり，一製品の時間的な盛衰サイクルを追うものではない。`
