    diff: `mid`,
    q: `あるメーカーが「他社が20年かけても真似できないミニチュアモーターの精密加工技術」を経営の要として差別化を図っている。この技術のように，顧客価値を生み出し，競合が模倣困難で，複数の市場へ応用できる企業固有の中核能力を表す用語として最も適切なものはどれか。`,
