    diff: `mid`,
    q: `スクラム開発チームに参加した新メンバーが「スプリント計画の前に何を見て作業を決めるのか」と質問した。プロダクトオーナーが優先順位付きで全要求を管理しているリストとして正しいものはどれか。`,
