    diff: `mid`,
    q: `新システム導入プロジェクトで，経営層・業務部門・外部ベンダーなど関係者が多様なため，各関係者の影響力と関心度を整理して個別にコミュニケーション計画を立てることになった。この活動はどれか。`,
