    point: `外れ値に強い代表値＝中央値。平均値は外れ値に直接引っ張られる。「億万長者が1人いると街の平均年収が跳ね上がる→その街の中央値は変わらない」。`,
    mem: `「平均じゃなくて、**中央**は端っこに引っ**張られない**」→ 億万長者が来ても真ん中は動かない。`,
