        text: `従量課金制（ペイアズユーゴー）`,
        correct: true,
        why: `従量課金制（Pay-as-you-go）は使った量（処理時間・データ量・リクエスト数等）に応じて料金が変動するモデル。毎月使用量が変われば請求額も変わるのが特徴。AWSやAzureが代表例で、使わなければ安くなる。`
