    mem: `CSR＝「**C**oえて**S**oclに**R**esponsibility」→ "C=超えて・S=社会に・R=責任"3文字一致。法律守るだけ（コンプライアンス）じゃなくて、法律を**超えて**社会に責任とるのがCSR。`,
