    diff: `hard`,
    q: `スタートアップが新しいドローン配送サービスを開発したが，現行の航空法規制では実証実験もできない。政府がこの企業に対し，一定条件のもとで既存規制の適用を一時的に留保しながら実験を許可する制度を利用した。この制度として最も適切なものはどれか。`,
