    point: `「提供するかどうかを自分で決める」＝情報自己決定権。「移す」＝ポータビリティ権，「消す」＝忘れられる権利，「広く私生活保護」＝プライバシー権，と目的で区別する。`,
    mem: `「JK（女子高生）が自分の投稿，**自分で**決める権利」→ JK＝自己決定の略（**自**己決定・J**K**）。「移す」ポータビリティ権・「消す」忘れられる権利とは別物。`,
