        text: `秘密保持契約（NDA）の締結`,
        correct: true,
        why: `NDA（Non-Disclosure Agreement）は機密情報を共有する前に相手方と締結する法的契約で，情報の目的外使用・第三者漏洩を禁止する。設計図のような営業秘密の共有には必須の法的手段。`
