    point: `「業務プロセス全体をまるごと外部委託」＝BPO。人材派遣は「人を借りる（指揮は自社）」，ITOは「IT基盤を委託」，SaaSは「ツールを借りる」。仕事ごと任せるのはBPOだけ。`,
    mem: `BPO＝「**B**usiness**P**rocess**O**まかせ！」→ B=Business／P=Process／O=お任せ。業務ごとバサッと投げる＝BPO。人は借りない・ITだけでもない。`,
