    point: `アンバンドリング＝バンドル（束）を解く＝一体提供→個別分離。反対のバンドリング（まとめる）とセットで，「分ける」か「まとめる」かで区別する。`,
    mem: `「**アン**ドゥ（Ctrl+Z）でバラバラ」→ アン＝解除，バンドル（束）をCtrl+Zで取り消す＝アンバンドリング。バンドリング（まとめる）じゃなくて，アン（解除）でバラバラが正解。`,
