    point: `CSIは「PDCAで継続的にサービス品質を改善する活動」。インシデント管理＝今の障害を直す、変更管理＝変更を安全に実施、SLM＝目標値を管理、CSI＝全体を通じた継続改善、と役割を区別する。`,
    mem: `「C（ちゃんと）S（サービス）I（改め続ける）」→ PDCAで終わりなく回す＝継続的サービス改善`,
