    diff: `mid`,
    q: `社内メールシステムの遅延インシデントが先月から繰り返されている。毎回その場で復旧させているが根本的には解決しない。ITILにおいて、繰り返すインシデントの根本原因を特定して恒久対策を講じる管理活動はどれか。`,
