    point: `「繰り返すインシデントの根本原因を特定して恒久対策」＝問題管理。インシデント管理は応急処置、問題管理は根治。"今すぐ直す（応急）"と"なぜ起きるか突き止める（根治）"の対比で区別する。`,
    mem: `インシデント管理じゃなくて、問題（モン）の根っこ（ダイ）を掘って恒久対策`,
