        why: `ペネトレーションテスト（侵入テスト）は，ホワイトハッカーが実際の攻撃と同じ手法でシステムへの侵入を試み，攻撃経路・脆弱性を特定するテスト。ツール任せでなく人が攻撃を再現する点が特徴。`
