    point: `「正しく機能するか＝機能適合性」「壊れずに動くか＝信頼性」「使いやすいか＝使用性」と3つを軸で区別する。"正確性・完全性・適切性"という3サブ特性が「適合性」に入るのが試験のポイント。`,
    mem: `機能適合性＝「正・完・適」3兄弟（**正**確・**完**全・**適**切）。信頼性（壊れにくさ）じゃなくて、「機能が正しく揃ってるか」がテキ合性。`,
    detailSlug: `itp-functional-suitability`
