    point: `PMBOKの「立ち上げプロセス群」で最初に作られるのはプロジェクト憲章のみ。WBS・スコープ記述書・リスク台帳はすべて計画フェーズの成果物。"PMが公式に任命され権限を与えられる根拠文書"が憲章。`,
    mem: `**ケン**（憲）章＝「**ケン**カ前に**ケン**を認める」＝開始の公式宣言。WBSじゃなくて、ケン章が一番最初。`,
