    point: `変更管理の3類型：標準変更（事前承認済み手順）・通常変更（CAB承認）・緊急変更（簡略手続き＋事後承認）。緊急変更は「先に直して，後で承認」が核心。`,
    mem: `緊急変更＝「キン（緊）急だから，キン（金）払ってから領収書もらう」→先に払って（対応して）後で証拠（承認）をもらう，という順番が耳に残る。`,
