    point: `認証（誰か）委譲＝OpenID Connect、認可（何をしていいか）委譲＝OAuth 2.0。SAMLは企業SSO向けのXMLベース。「Googleでログイン」はOpenID Connect一択。`,
    mem: `OpenID Connectじゃなくて、OAuthは権限だけ。→ OpenID＝「**ID**カード**コネクト**（接続）」で"誰か"証明、OAuthは「**権限カード**だけ」でIDカード持っていない。`,
