        why: `Product as a Serviceは「製品を売る」から「製品の使用価値をサービスとして継続提供する」への転換モデル。IoTで稼働データを取得し，予知保全・使用量課金・継続アップデートを組み合わせる。コピー機→印刷枚数課金が典型例。`
