    point: `産業設備（工場・インフラ）＋IoT＋クラウド＋AI＝IIoT。BEMSはビルのエネルギー管理，SCADAは制御システムの手段，スマートグリッドは電力網の概念。対象領域で切り分ける。`,
    mem: `「BEMSじゃなくて、**工場**にIoT＝IIoT」→ BEMSはビルのエネルギー管理、スマートグリッドは電力網、工場・インフラにセンサを刺してクラウドで診るのがIIoT。`,
