    point: `SCMは「誰が何をするか」でなく「川上から川下まで全体をまとめて管理する」概念。EDI・オープンAPI・データスペースはいずれも「手段・技術・基盤」の話。SCMだけが管理概念＝全体最適の担い手。`,
