    point: `テレワークの課題は①技術面（セキュリティ）と②人間面（孤立・マネジメント）の2軸で押さえる。賃料増加・会議室不足・通勤増加はいずれもテレワークと逆方向の現象なので素早く排除できる。`,
    mem: `テレワーク課題＝「**セ**キュリティと**コ**ドク」——「セ」「コ」の2文字で即答。`,
