    id: `itp-q275`,
    cat: `ストラテジ`,
    diff: `easy`,
    q: `あるコスメブランドが，多くのフォロワーを持つSNSユーザーに商品を提供し，そのユーザーが自発的に使用感をSNSに投稿することでブランド認知を拡大させた。この人物を何というか。`,
