    point: `インフルエンサー・アンバサダー・アフィリエイターは全員「企業と関わる人」で混同しやすい。インフルエンサー＝SNS影響力（フォロワー）・アンバサダー＝公式契約代表・アフィリエイター＝成果報酬リンク。`,
    mem: `インフルエンサー＝「**イン**フル（インフルエンザ）みたいに広がる人」——インフルエンザが感染拡大するように，口コミを広める。`,
