    point: `中小企業のIT投資判断の軸は「経営目標との整合性×費用対効果」。最先端・横並び・補助金ありきはいずれも本末転倒。`,
    mem: `IT投資＝「最先端じゃなくて、**経営目標に合うか**」→補助金・横並び・最先端ありきはすべて本末転倒。`,
