    diff: `easy`,
    q: `在宅勤務中，ビデオ会議をしながら資料を画面に映している。同居の家族や通りがかりの人に画面を見られるリスク（ショルダーハッキング）を防ぐ直接的な対策として最も適切なものはどれか。`,
