    point: `「見られる」脅威＝物理的対策（フィルタ・配置）で防ぐ。VPN・パスワード・FWはネットワーク経由の脅威に対応するもの。脅威の種類と対策の種類を必ず対応させる。`,
    mem: `ショルダー＝「肩（目線）からのぞく」→ VPNじゃなくて、フィルタで目を塞げ！`,
    detailSlug: `itp-shoulder-hacking`
