        why: `エッジコンピューティングはデータ発生源（工場のセンサ）の近くにある処理装置（エッジサーバ）で前処理・集約し，必要なデータだけクラウドへ送る。帯域消費の削減・遅延低減・プライバシー保護の3つを同時に解決できる。`
