    point: `エッジコンピューティングのキーワードは「現場の近く」「リアルタイム」「帯域節約」。IoT・工場・自動車などデータ量が多く遅延が困る場面が出てきたらエッジを疑う。クラウドとの対比で"どこで処理するか"が問われている。`,
