    diff: `mid`,
    q: `電子契約を締結したとき，「この契約書は2025年4月1日15時に存在した」という事実と，その後改ざんされていないことをTSA（時刻認証局）が証明するサービスを利用したい。このサービスとして適切なものはどれか。`,
