    id: `itp-q400`,
    cat: `マネジメント`,
    diff: `hard`,
    q: `自社のITガバナンス体制を整備するため，経営目標とITプロセスを体系的に連結するフレームワークを採用することになった。ITプロセスを複数のドメインに分類・体系化したITガバナンス専用のフレームワークはどれか。`,
