    id: `itp-q421`,
    cat: `テクノロジ`,
    diff: `hard`,
    q: `新作ゲームで，光が物体に当たって反射・屈折し，リアルな影が落ちる映像を生成したい。このような光の経路を物理的に計算して映像を作る手法はどれか。`,
