    cat: `テクノロジ`,
    diff: `mid`,
    q: `ECサイトの注文テーブルに「商品ID」列があり、存在しない商品IDを注文データに入力しようとしたがエラーになった。この動作を実現しているデータベースの制約はどれか。`,
