    point: `「モデルが自分で学習できない外側の設定値」＝ハイパーパラメータ。人間が試行錯誤して最良値を探す＝チューニング。学習中に自動更新される「重み（パラメータ）」と混同しないこと。`,
    mem: `パラメータはパン生地（モデルが自分でこねる）、ハイパーは外からかけるパン粉！`,
    detailSlug: `itp-hyperparameter-tuning`
