    point: `社外取締役＝経営の「外部の監視役」。業務を執行するのではなく、経営陣を監督・牽制して株主利益を守ることが本質。`,
    mem: `社外取締役＝「そ（外）と（取）で締める」→外から内輪の馴れ合いを締め上げる人。`,
