    q: `EU域内のユーザーデータを扱うWebサービスを運営している。GDPR（一般データ保護規則）への対応として正しいものはどれか。`,
    choices: [
      {
        text: `収集した個人データは登録時に明示した目的にのみ使用する仕組みを設ける`,
        correct: true,
        why: `GDPRの「目的限定の原則」は、個人データは特定・明示・正当な目的のためにのみ収集・処理しなければならないと定める。例えば配送のために集めた住所をマーケティングに転用することは原則禁止。`
      },
      {
        text: `個人データは必要に応じていつまでも保管してよい`,
        correct: false,
        why: `GDPRは「保存制限の原則」として、目的達成後は速やかにデータを削除または匿名化することを求める。無期限保管はGDPR違反。「保管期限なし」は典型的な誤り。`
      },
      {
        text: `収集目的に関わらず、広告・マーケティング・研究など任意の用途に使える`,
        correct: false,
        why: `GDPRは目的外利用を原則禁止している。収集時に開示した目的と異なる用途に使う場合は本人の新たな同意が必要。「目的を問わず任意に使える」は目的限定の原則への直接の違反。`
      },
      {
        text: `グループ会社内であれば個人データを自由に共有・活用できる`,
        correct: false,
        why: `GDPR上、グループ会社間の共有であっても第三者提供に準じる扱いが求められる。法的根拠（本人同意・正当な利益等）なしには自由な共有は認められない。「グループ内なら自由」は典型的な誤解。`
      }
    ],
    point: `GDPRの核心は「目的限定の原則」。収集時に申告した目的以外には使えない。「無期限保管」「任意の目的」「グループ内は自由」はすべてGDPR違反のひっかけ。`,
    mem: `「グループ内は自由じゃなくて、GDPRは目的以外NG」。Gゴリラ・Dデータ・Pプロテクション・Rルール＝目的外渡したらゴリラに怒られる。`,
