    cat: `テクノロジ`,
    diff: `hard`,
    q: `病気の早期発見AIを開発した。データは「正常」98%・「異常」2%のクラス不均衡。モデルの評価指標として正解率（Accuracy）よりF1スコアを使うべき理由として正しいものはどれか。`,
    choices: [
      {
        text: `クラス不均衡データでもPrecisionとRecallを両立して評価できるから`,
        correct: true,
        why: `Accuracyは「全部を正常と予測するだけで98%」になる欠陥がある。F1スコアはPrecision（正と予測して実際に正の割合）とRecall（実際に正のものを正と予測できた割合）の調和平均で、少数クラス（異常）の検出性能を正しく評価できる。`
      },
      {
        text: `F1スコアは回帰問題（数値予測）に使う指標だから`,
        correct: false,
        why: `F1スコアは分類問題の評価指標。回帰問題にはMAEやRMSEを使う。「回帰に使う」は完全な誤り。F1の使い所を問われたら「分類」と即答できること。`
      },
      {
        text: `AccuracyはF1スコアの特殊ケースに過ぎないから`,
        correct: false,
        why: `AccuracyとF1は別の指標体系。F1はPrecision・Recallの調和平均であり、AccuracyがF1の特殊ケースという数式的・定義的な関係はない。上位互換・下位互換の関係でもない。`
      },
      {
        text: `F1スコアはAccuracyより常に低い値を示すから`,
        correct: false,
        why: `F1スコアとAccuracyの大小関係はデータ次第。クラスが均衡なケースではF1とAccuracyが近い値を示すこともある。「常に低い」は誤り。大小で優劣を判断するのではなく、何を測りたいかが使い分けの基準。`
      }
    ],
    point: `クラス不均衡（病気・不正検知等で少数クラスが重要）ではAccuracyが無意味になる。F1スコア＝PrecisionとRecallの調和平均＝少数クラスの検出力を測る。`,
    mem: `「Accuracyじゃなくて、不均衡はF1」。全部正常予測で98%取れちゃうAccuracyは赤ちゃん指標。不均衡コースを走り切るのがF1レース。`,
