    diff: `mid`,
    q: `ITヘルプデスクが，従業員が「どのサービスを，どんな条件で，どう申請すれば使えるか」を自分で確認できるよう，提供サービスをまとめた文書を整備した。このITSM文書の名称はどれか。`,
