    diff: `mid`,
    q: `システム部門が大量の写真ファイルをクラウドに保存するサービスを選定している。フォルダ階層は不要で、膨大な量を低コストで保存しAPIでアクセスしたい場合に最も適したクラウドストレージ方式はどれか。`,
