        why: `セッションIDが連番や単純な値だと，攻撃者が有効IDを推測・総当たりで入手し他ユーザーのセッションを乗っ取るセッションハイジャックが可能になる。推測困難な乱数にすることで攻撃者がIDを当てられなくなる。`
