        why: `RSAは「巨大な数の素因数分解が従来コンピュータでは現実的な時間内に解けない」ことを安全性の根拠にしている。量子コンピュータのShorアルゴリズムはこの素因数分解を指数関数的に高速化するため，RSAが理論上解読可能になる。`
