    point: `「サイバーセキュリティの基本方針＋NISC設置根拠＝サイバーセキュリティ基本法」。個人情報保護法・不正アクセス禁止法・電子署名法はいずれも国全体のサイバーセキュリティ推進体制を定めたものではない。`,
    mem: `個人情報保護法じゃなくて、NISCの根拠はサイバーセキュリティ基本法＝「ニスク（NISC）の家（基本法）はサイバーの番地」。`,
