    point: `ユーザーストーリーの形式は「ユーザーとして〜したい，なぜならば〜だから」。UML・フローチャート・機能要件書との違いは「誰のために・なぜ」という価値視点が入っているかどうか。`,
    mem: `ユーザーストーリーじゃなくて、UML・フロー・仕様書はどれも「なぜ」が抜ける。「主人公（ユーザー）・やりたい（したい）・なぜ」の3点セット。`,
