    point: `事前学習済みモデルを新タスクに流用＝転移学習。そのうえで少量データで追加学習して微調整するのがファインチューニング。強化学習・ゼロショット・連合学習との区別が頻出。`,
    mem: `転移学習じゃなくて、強化学習は報酬ゲーム・ゼロショットはデータ0件・連合学習はデータ持ち寄り。転移＝「前の会社（大規模モデル）の知識を転職先（新タスク）に持ち込む」。`,
